偽代碼：
```typescript
// src/modules/audit/decorators/auditable.decorator.ts
function Auditable(eventType: AuditEventType) {
  return function(target: any, key: string, descriptor: PropertyDescriptor) {
    const original = descriptor.value;
    descriptor.value = async function(...args: any[]) {
      const result = await original.apply(this, args);
      await auditService.log({
        event_type: eventType,
        actor_uid: getCurrentUser().uid,
        target_type: extractTargetType(args),
        target_id: extractTargetId(args),
        action: key,
        details: extractDetails(args, result)
      });
      return result;
    };
  };
}
```

1. 版本生命週期狀態機（M4-1）：
```typescript
const versionLifecycle = createStateMachine({
  initial: 'draft',
  states: {
    draft: { on: { SUBMIT: 'validating' } },
    validating: {
      on: {
        VALIDATION_PASSED: 'review_required',
        VALIDATION_FAILED: 'draft'
      }
    },
    review_required: {
      on: {
        APPROVE: 'published',
        REJECT: 'draft'
      }
    },
    published: {
      on: {
        DEPRECATE: 'deprecated',
        DELIST: 'delisted',
        EMERGENCY_DISABLE: 'emergency_disabled'
      }
    },
    deprecated: {
      on: {
        DELIST: 'delisted',
        EMERGENCY_DISABLE: 'emergency_disabled'
      }
    },
    delisted: {
      on: { EMERGENCY_DISABLE: 'emergency_disabled' }
    },
    emergency_disabled: { type: 'final' }
