2. 字段白名單校驗（M5-2）：
```typescript
const ALLOWED_FIELDS = new Set([
  'idempotency_key', 'package_id', 'version',
  'user_ref', 'user_ref_type', 'os_type',
  'status', 'error_code', 'start_time', 'end_time'
]);

function validateTelemetry(payload: any): TelemetryEvent {
  // 丟棄白名單外字段並記錄異常
  const extra = Object.keys(payload).filter(k => !ALLOWED_FIELDS.has(k));
  if (extra.length > 0) {
    logger.warn('Dropped extra telemetry fields', { extra });
  }

  return pick(payload, [...ALLOWED_FIELDS]) as TelemetryEvent;
}
```

