偽代碼：
```typescript
// 升級差異計算
interface VersionDiff {
  addedPermissions: Permission[];
  removedPermissions: Permission[];
  changedCommands: CommandDiff[];
  releaseNotes: string;
  requiresReapproval: boolean;
}

async function calculateVersionDiff(
  currentVersion: string,
  targetVersion: string
): Promise<VersionDiff> {
  const current = await versionRepo.findByVersion(currentVersion);
  const target = await versionRepo.findByVersion(targetVersion);

  return {
    addedPermissions: difference(target.permissions, current.permissions),
    removedPermissions: difference(current.permissions, target.permissions),
    changedCommands: diffCommands(current.script, target.script),
    releaseNotes: target.releaseNotes,
    requiresReapproval: hasNewSensitivePermissions(target, current)
  };
}
```

